const event=$input.first().json,execution=event.execution||{};
const err=execution.error||event.trigger?.error||{};
const name=String(execution.lastNodeExecuted||err.node?.name||'Trigger or unknown node').slice(0,100);
const ai=name==='Stop failed agent briefing';
const knownTypes=['NodeApiError','NodeOperationError','Error','WorkflowActivationError','ExpressionError'];
const type=knownTypes.includes(err.name)?err.name:'ExecutionError';
const status=/^[1-5][0-9]{2}$/.test(String(err.httpCode||err.statusCode||''))?String(err.httpCode||err.statusCode):null;
return [{json:{
 workflow_name:'Meeting Prep AI Agent',
 failed_node:ai?'Write prep briefing / Validate saved briefing':name,
 error_message:ai?'AI briefing failed after extraction/validation; requester notification attempted.':type+(status?' (HTTP '+status+')':'')+'. Inspect the failed node configuration; original message and content intentionally omitted.',
 failed_input:{available:false,reason:'Intentionally omitted: no transcript, briefing, response_url, request headers or customer data is logged.'},
 execution_id:execution.id?String(execution.id):null
}}];
